{"code":"import json
import numpy as np
import pandas as pd

with open('evaluations.json') as f:
    data = json.load(f)

# Let's categorize ingredients into functional groups:
# Proteins, Solid Fats, Liquid Oils, Starches/Carbs, Binders, Flavors/Savory, Colors/Juices
proteins = {'textured vegetable protein', 'pea protein', 'soy protein concentrate', 'soy protein isolate', 'potato protein', 'brown rice protein', 'wheat gluten'}
solid_fats = {'coconut oil', 'palm oil', 'shea butter'}
liquid_oils = {'sunflower oil', 'canola oil', 'soybean oil', 'corn oil', 'avocado oil', 'olive oil', 'shea oil', 'soya bean oil'}
starches = {'potato starch', 'corn starch', 'tapioca starch', 'wheat starch', 'starch'}
binders = {'methylcellulose', 'carrageenan', 'agar agar', 'gellan', 'konjac powder', 'acacia gum'}
savory = {'flavours', 'yeast extract', 'onion', 'garlic', 'white pepper', 'liquid smoke', 'smoke flavouring', 'plant flavors'}
color = {'plain caramel', 'vegetable juice', 'radish juice', 'fruit juice', 'natural vegetable color', 'anthocyanins', 'tomato paste'}

for d in data:
    r = {x['ingredient']: x['fraction'] for x in d['recipe']}
    p = sum(v for k, v in r.items() if k in proteins)
    sf = sum(v for k, v in r.items() if k in solid_fats)
    lo = sum(v for k, v in r.items() if k in liquid_oils)
    st = sum(v for k, v in r.items() if k in starches)
    bi = sum(v for k, v in r.items() if k in binders)
    sa = sum(v for k, v in r.items() if k in savory)
    co = sum(v for k, v in r.items() if k in color)
    print(f"Iter {d['iteration']:2d}: y={d['target_dissimilarity']:.4f} | P={p:.3f}, SF={sf:.3f}, LO={lo:.3f}, Fat={sf+lo:.3f}, St={st:.3f}, Bi={bi:.3f}, Sa={sa:.3f}, Co={co:.3f}")
"}

{"code":"import json
import numpy as np

with open('evaluations.json') as f:
    data = json.load(f)

cols = ['textured vegetable protein', 'pea protein', 'coconut oil', 'sunflower oil', 'potato starch', 'flavours', 'methylcellulose', 'yeast extract', 'plain caramel']
pts = []
for d in data:
    if d['iteration'] in [1, 5, 6, 7, 8, 9, 10, 11, 12]:
        vec = [ next((r['fraction'] for r in d['recipe'] if r['ingredient']==c), 0.0) for c in cols ]
        pts.append((d['iteration'], d['target_dissimilarity'], np.array(vec)))

for it, y, v in pts:
    print(f"Iter {it:2d}: y={y:.6f} | TVP={v[0]:.4f}, Pea={v[1]:.4f}, Coco={v[2]:.4f}, Sun={v[3]:.4f}, Pot={v[4]:.4f}")
"}

{"code":"import json
import numpy as np
import pandas as pd

with open('evaluations.json') as f:
    data = json.load(f)

cols = ['textured vegetable protein', 'pea protein', 'coconut oil', 'sunflower oil', 'potato starch', 'flavours', 'methylcellulose', 'yeast extract', 'plain caramel']
rows = []
for d in data:
    if d['iteration'] not in [2, 3, 4]:
        r = {x['ingredient']: x['fraction'] for x in d['recipe']}
        row = [r.get(c, 0.0) for c in cols]
        rows.append((d['iteration'], d['target_dissimilarity'], row))

for it, y, r in sorted(rows, key=lambda x: x[1]):
    print(f"Iter {it:2d}: y={y:.6f} | {[round(v, 4) for v in r]}")
"}

